package com.sehatharian.controller;
import com.sehatharian.content.ContentService;
import com.sehatharian.content.ContentService.*;
import com.sehatharian.model.*;
import com.sehatharian.catalog.TeamExercises;
import com.sehatharian.util.*;
import static com.sehatharian.util.HabitUI.*;
import javafx.fxml.FXML;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import java.util.*;
public final class AdminController implements AutoCloseable {
    private final SessionAccess access;private final ContentService service;private final WriteAction writes;
    @FXML private VBox page;
    private final ComboBox<Kind> kind=new ComboBox<>();private final TextField query=new TextField(),title=new TextField();private final TextArea body=new TextArea();
    private final VBox list=new VBox(8),editor=new VBox(12),stepRows=new VBox(8);private final Label notice=text("");
    private final ComboBox<Content> movement=new ComboBox<>();private final Spinner<Integer> target=new Spinner<>(1,3600,30);private final CheckBox reps=new CheckBox("Repetisi manual");
    private final List<Step> steps=new ArrayList<>();private Content selected;private TrainingVideo video;private MenuCompositionEditor menuEditor;private IngredientAdminPane ingredientAdmin;
    public AdminController(UserSession session){access=new SessionAccess(session);access.requireAdmin();service=new ContentService(access);writes=new WriteAction(access);}
    @FXML public void initialize(){HabitUI.page(page,"Kelola konten","Draft → Ditinjau → Diterbitkan → Diarsipkan · katalog gizi impor dikelola terpisah");kind.getItems().addAll(Kind.values());kind.setValue(Kind.MOVEMENT);body.setPrefRowCount(5);body.setWrapText(true);
        ingredientAdmin=new IngredientAdminPane(access);var ingredientPanel=new TitledPane("Kelola bahan & alias",ingredientAdmin);ingredientPanel.setExpanded(false);
        page.getChildren().addAll(notice,ingredientPanel,action("Menu resep",()->{kind.setValue(Kind.MENU);edit(null);}),field("Jenis konten",kind),field("Pencarian judul",query),action("Cari konten",this::reload),action("Buat konten baru",()->edit(null)),list,editor);kind.setOnAction(e->{selected=null;editor.getChildren().clear();reload();});reload();}
    public void reload(){access.requireAdmin();list.getChildren().clear();try{var items=service.adminList(kind.getValue(),query.getText());if(items.isEmpty())list.getChildren().add(state(HabitUI.State.EMPTY,"Belum ada konten jenis ini."));for(var item:items){String category=item.kind()==Kind.MOVEMENT?TeamExercises.find(item.body()).map(c->"/images/team/"+c.file().replace(".mp4",".jpg")).orElse("routine"):item.kind()==Kind.MENU?"nutrition":item.kind()==Kind.CHALLENGE?item.body().split("\\|")[0]:"routine";WellnessArt art=new WellnessArt(category,56);art.setPrefWidth(64);art.setMaxWidth(64);Button open=action(item.title()+" · "+item.state()+" · v"+item.revision(),()->edit(item));HBox.setHgrow(open,Priority.ALWAYS);HBox row=new HBox(10,art,open);row.setAlignment(javafx.geometry.Pos.CENTER_LEFT);list.getChildren().add(row);}}catch(Exception e){list.getChildren().add(state(HabitUI.State.ERROR,"Daftar admin belum tersedia."));}}
    private void edit(Content item){access.requireAdmin();if(menuEditor!=null){menuEditor.close();menuEditor=null;}if(video!=null){video.close();video=null;}selected=item;steps.clear();title.setText(item==null?"":item.title());body.setText(item==null?"":item.body());editor.getChildren().setAll(text(item==null?"Konten baru":"Revisi dari "+item,"habit-heading"),field("Judul",title),field("Isi / konfigurasi",body));
        if(kind.getValue()==Kind.MOVEMENT){ComboBox<String> clip=new ComboBox<>();clip.getItems().addAll(TeamExercises.ALL.stream().map(c->c.exercise().externalId()).toList());clip.setOnAction(e->{body.setText(clip.getValue());if(video!=null)video.close();video=new TrainingVideo(TeamExercises.find(clip.getValue()).orElseThrow(),true);editor.getChildren().removeIf(n->n instanceof TrainingVideo);editor.getChildren().add(video);});editor.getChildren().add(field("Video tim",clip));if(item!=null)clip.setValue(item.body());}
        if(kind.getValue()==Kind.MENU){try{var composition=item==null?com.sehatharian.nutrition.MenuModels.Composition.unknown():new com.sehatharian.nutrition.MenuComposition(access).admin(item.id()).composition();menuEditor=new MenuCompositionEditor(access,composition);editor.getChildren().add(menuEditor);}catch(Exception e){notice.setText("Pemetaan menu gagal dimuat. Buka ulang sebelum menyimpan.");return;}}
        if(kind.getValue()==Kind.CHALLENGE)editor.getChildren().add(text("Kriteria: sleep|5 (jam), hydration|1500 (ml), nutrition|3 (catatan), activity|20 (menit). Alasan dan catatan tersimpan menentukan penyelesaian."));
        if(kind.getValue()==Kind.PROGRAM){try{movement.getItems().setAll(service.adminList(Kind.MOVEMENT,""));if(item!=null)steps.addAll(service.preview(item.id()).steps());}catch(Exception e){notice.setText("Langkah belum dapat dimuat.");}
            editor.getChildren().addAll(field("Gerakan (versi konten)",movement),field("Target detik / repetisi",target),reps,action("Tambahkan langkah",()->{if(movement.getValue()!=null){steps.add(new Step(movement.getValue().id(),target.getValue(),reps.isSelected()));renderSteps();}}),stepRows);renderSteps();}
        editor.getChildren().add(action("Preview isian",()->{access.requireAdmin();try{ContentService.validate(kind.getValue(),title.getText(),body.getText(),steps);notice.setText("Preview: "+title.getText()+"\n"+body.getText()+"\n"+steps);}catch(Exception e){notice.setText("Validasi: "+e.getMessage());}}));
        editor.getChildren().add(write("Simpan sebagai draft revisi",()->{int id=kind.getValue()==Kind.MENU?service.saveMenuDraft(selected==null?null:selected.id(),title.getText(),body.getText(),menuEditor.value()):service.saveDraft(selected==null?null:selected.id(),kind.getValue(),title.getText(),body.getText(),List.copyOf(steps));selected=service.adminList(kind.getValue(),"").stream().filter(c->c.id()==id).findFirst().orElseThrow();return true;}));
        if(item!=null){if(item.state()==ContentService.State.DRAFT)editor.getChildren().add(write("Tandai ditinjau",()->service.transition(item.id(),ContentService.State.REVIEWED)));if(item.state()==ContentService.State.REVIEWED)editor.getChildren().add(write("Terbitkan",()->service.transition(item.id(),ContentService.State.PUBLISHED)));if(item.state()!=ContentService.State.ARCHIVED)editor.getChildren().add(write("Arsipkan",()->service.transition(item.id(),ContentService.State.ARCHIVED)));}}
    private Button write(String name,SessionAccess.Operation<Boolean> action){Button b=HabitUI.action(name,()->{access.requireAdmin();try{writes.submit(page,action,()->{notice.setText("Perubahan konten tersimpan.");editor.getChildren().clear();reload();});}catch(Exception e){notice.setText("Konten belum berubah: "+e.getMessage());}});b.getStyleClass().add("write-command");if(name.startsWith("Simpan")||name.equals("Terbitkan"))VisualUI.primary(b);return b;}
    private void renderSteps(){stepRows.getChildren().clear();for(int i=0;i<steps.size();i++){int n=i;Step s=steps.get(i);VBox row=card("Langkah "+(i+1),text("Gerakan versi #"+s.movementId()+" · "+s.target()+(s.repetitions()?" repetisi":" detik")));AdaptiveRow actions=new AdaptiveRow(6);if(i>0)actions.getChildren().add(action("Naik",()->{Collections.swap(steps,n,n-1);renderSteps();}));if(i<steps.size()-1)actions.getChildren().add(action("Turun",()->{Collections.swap(steps,n,n+1);renderSteps();}));actions.getChildren().add(action("Hapus langkah",()->{steps.remove(n);renderSteps();}));row.getChildren().add(actions);stepRows.getChildren().add(row);}}
    @Override public void close(){if(menuEditor!=null)menuEditor.close();if(ingredientAdmin!=null)ingredientAdmin.close();if(video!=null)video.close();access.close();editor.getChildren().clear();}
}
